 void CompleteOriginalPrintMenu(){canvas.RebuildGuideMeasurement=true;canvas.LayoutScore();originalPrintMenuActive=NativePrintMenuChoice.Original;if(printJob==null)printJob=NativePrintJob.Defaults(source);printStage=OriginalPrintStage.None;printMenuNotice="";mode=ScreenMode.Print;UpdateClassic();LayoutClassic();RefreshOriginalPrintMenu();}
 static string PrintFlag(bool value){return value?"Yes":"No";}
