 string OriginalPrintMenuText(){var p=printJob;string paper=p.PaperWidth==8.5f&&p.PaperHeight==11?"Letter":p.PaperWidth==8.5f&&p.PaperHeight==14?"Legal":p.PaperWidth==11&&p.PaperHeight==17?"Ledger":"";var b=new StringBuilder();Action<string> line=s=>b.Append(s).Append(Environment.NewLine);
 line("");line("═════ Laser Printing Parameters (1=yes, 0=no) ═════"+(printMenuDirty?" *":String.IsNullOrEmpty(printMenuFile)?"":"  "+printMenuFile));line("");line(" 1. OUTPUT (<enter>=Laser--or give file name) =");line("       "+(String.IsNullOrEmpty(p.Output)||p.Output.Equals("Laser",StringComparison.OrdinalIgnoreCase)?"Laser":"PostScript file= "+p.Output));line(" 2. SIZE.............................="+PrintNumber(p.Size,3,7));line(" 3. PAPER size (Ltr, Leg, Ldg).......="+PrintNumber(p.PaperWidth,3,7)+" x "+PrintNumber(p.PaperHeight,3,6)+(paper.Length==0?"":"  "+paper));line("");line(" 4. OFFSETS  X(left), Y(bottom)......="+PrintNumber(p.Left/4000f,2,6)+","+PrintNumber(p.Bottom/4000f,2,6)+" in.");line(" 5. FREEZE offsets(Y/N)..............= "+PrintFlag(p.Freeze));line("");line(" 6. RESOLUTION.......................= "+p.Resolution+" dpi");line(" 7. LINE width.......................= "+p.LineWidth+" pixels");line(" 8. HEADER/FOOTER (H, F, or B)...... = "+p.Header);if(p.Header!="None"){line("         Project name = "+p.Project);if(p.Header!="Footer")line("         Header offset down from top = "+PrintNumber(p.HeaderOffset,3,6));if(p.Header!="Header")line("         Footer offset up from bottom= "+PrintNumber(p.FooterOffset,3,6));}line("");line(" 9. ROTATE (Y/N).....................= "+PrintFlag(p.Rotate));line("10. MIRROR (Y/N).....................= "+PrintFlag(p.Mirror));line("11. SETSTROKE (Y/N)..................= "+PrintFlag(p.Stroke));line("12. MANUAL feed (Y/N)................= "+PrintFlag(p.Manual));line("13. SETPAPERTRAY (0 - 9 )............= "+p.Tray);line("14. READ PRINT.SCR   15. SAVE PRINT.SCR"+(scor4Interface?"   F1=help":""));
