 void RefreshOriginalPrintMenu(){if(mode!=ScreenMode.Print||!UsesOriginalPrintMenu){if(originalPrintPanel!=null)originalPrintPanel.Visible=false;return;}if(printJob==null)printJob=NativePrintJob.Defaults(source);if(originalPrintPanel==null){originalPrintPanel=new Panel();originalPrintScroll=new Panel{Dock=DockStyle.Fill,AutoScroll=true};originalPrintLines=new NativeTextLabel{Wrapped=true};originalPrintEntry=new NativePrintCommandBox{Dock=DockStyle.Bottom,BorderStyle=BorderStyle.None,AppendOnly=()=>printStage==OriginalPrintStage.None};originalPrintEntry.KeyPress+=(s,e)=>{if(printStage==OriginalPrintStage.OutputOverwrite){e.Handled=true;Safe(()=>SubmitOriginalPrint(e.KeyChar.ToString()));}};originalPrintScroll.Controls.Add(originalPrintLines);originalPrintPanel.Controls.Add(originalPrintScroll);originalPrintPanel.Controls.Add(originalPrintEntry);Controls.Add(originalPrintPanel);Resize+=(s,e)=>{if(mode==ScreenMode.Print)RefreshOriginalPrintMenu();};}int topEdge=PointToClient(fileLine.PointToScreen(new Point(0,fileLine.Height))).Y;originalPrintPanel.SetBounds(0,topEdge,ClientSize.Width,Math.Max(1,ClientSize.Height-topEdge));originalPrintPanel.BackColor=responseLine.BackColor;originalPrintScroll.BackColor=responseLine.BackColor;originalPrintEntry.Font=classicFont;originalPrintEntry.ForeColor=responseLine.ForeColor;originalPrintEntry.BackColor=responseLine.BackColor;originalPrintEntry.Height=textRowHeight;originalPrintLines.Font=classicFont;originalPrintLines.LinePitch=textRowHeight;originalPrintLines.ForeColor=responseLine.ForeColor;originalPrintLines.BackColor=responseLine.BackColor;originalPrintLines.Text=OriginalPrintMenuText();int width=Math.Max(1,originalPrintScroll.ClientSize.Width-24-SystemInformation.VerticalScrollBarWidth);originalPrintLines.SetBounds(12,0,width,originalPrintLines.ContentHeight(width));originalPrintPanel.Visible=true;originalPrintPanel.BringToFront();if(letterHelpPages==null)originalPrintEntry.Focus();}
 bool OriginalPrintKey(KeyEventArgs key){if(mode!=ScreenMode.Print||letterHelpPages!=null)return false;if(!UsesOriginalPrintMenu){if(key.KeyCode==Keys.Escape){mode=ScreenMode.Main;UpdateClassic();LayoutClassic();command.Focus();key.SuppressKeyPress=true;return true;}if(key.KeyCode>=Keys.F1&&key.KeyCode<=Keys.F8){key.SuppressKeyPress=true;Safe(()=>Function((int)key.KeyCode-(int)Keys.F1+1));return true;}return false;}if(printStage==OriginalPrintStage.ReadAcknowledgement){if(key.KeyCode==Keys.ShiftKey||key.KeyCode==Keys.ControlKey||key.KeyCode==Keys.Menu||key.KeyCode==Keys.LWin||key.KeyCode==Keys.RWin){key.SuppressKeyPress=true;return true;}printStage=OriginalPrintStage.None;printMenuNotice="";RefreshOriginalPrintMenu();key.SuppressKeyPress=true;return true;}if(key.KeyCode==Keys.Escape){LeaveOriginalPrintMenu();key.SuppressKeyPress=true;return true;}if(key.KeyCode==Keys.Enter){key.SuppressKeyPress=true;string text=originalPrintEntry==null?command.Text:originalPrintEntry.Text;if(originalPrintEntry!=null)originalPrintEntry.Clear();Safe(()=>SubmitOriginalPrint(text));return true;}if(key.KeyCode>=Keys.F1&&key.KeyCode<=Keys.F12){key.SuppressKeyPress=true;if(printStage==OriginalPrintStage.None){if(key.KeyCode==Keys.F1)Safe(()=>ShowHelpTopic("PRINT"));else if(key.KeyCode==Keys.F6)Safe(RunOriginalPrint);}return true;}return true;}
 bool OriginalPrintCharacter(KeyPressEventArgs key){if(mode!=ScreenMode.Print||!UsesOriginalPrintMenu||letterHelpPages!=null)return false;if(printStage==OriginalPrintStage.OutputOverwrite&&!Char.IsControl(key.KeyChar)){key.Handled=true;Safe(()=>SubmitOriginalPrint(key.KeyChar.ToString()));return true;}if(originalPrintEntry!=null&&!originalPrintEntry.Focused&&!Char.IsControl(key.KeyChar)){originalPrintEntry.Focus();originalPrintEntry.AppendText(key.KeyChar.ToString());key.Handled=true;}return true;}
 static float PrintValue(string value){float n;if(!Single.TryParse(value,NumberStyles.Float,PrintCulture,out n)||Single.IsInfinity(n)||Single.IsNaN(n))throw new InvalidDataException("Enter a finite print value.");return n;}
 static short PrintWord(string value){float n=PrintValue(value);if(n!=Math.Truncate(n)||n<short.MinValue||n>short.MaxValue)throw new NotSupportedException("This print control requires an integer value.");return (short)n;}
 static bool PrintBoolean(string text){if(text=="Y"||text=="1")return true;if(text.Length==0||text=="N"||text=="0")return false;throw new InvalidDataException("Enter Y, N, 1 or 0.");}
 bool SubmitOriginalPrint(string input){if(mode!=ScreenMode.Print||!UsesOriginalPrintMenu||letterHelpPages!=null)return false;string text=input.Trim(),upper=text.ToUpperInvariant();printMenuNotice="";
 if(printStage==OriginalPrintStage.OutputOverwrite){if(upper=="Y"){printJob.Output=pendingPrintOutput;printStage=OriginalPrintStage.None;printMenuDirty=true;}else if(upper=="N")printStage=OriginalPrintStage.None;RefreshOriginalPrintMenu();return true;}
 if(printStage==OriginalPrintStage.Project){if(input.Length>18)throw new InvalidDataException("Project names are limited to18 characters.");pendingPrintProject=input;pendingHeaderOffset=printJob.HeaderOffset;pendingFooterOffset=printJob.FooterOffset;printStage=pendingPrintHeader=="Footer"?OriginalPrintStage.FooterOffset:OriginalPrintStage.HeaderOffset;RefreshOriginalPrintMenu();return true;}
 if(printStage==OriginalPrintStage.HeaderOffset){if(text.Length!=0)pendingHeaderOffset=NativePrintJob.HeaderInput(PrintValue(text),pendingHeaderOffset);if(pendingPrintHeader=="Both")printStage=OriginalPrintStage.FooterOffset;else CommitPrintHeader();RefreshOriginalPrintMenu();return true;}
 if(printStage==OriginalPrintStage.FooterOffset){if(text.Length!=0)pendingFooterOffset=NativePrintJob.FooterInput(PrintValue(text),pendingFooterOffset);CommitPrintHeader();RefreshOriginalPrintMenu();return true;}
 if(printStage==OriginalPrintStage.ReadFile||printStage==OriginalPrintStage.SaveFile){if(text.Length==0)text="PRINT.SCR";bool reading=printStage==OriginalPrintStage.ReadFile;string path=Path.GetFullPath(text);if(reading)printJob=NativePrintJob.Read(path,printJob);else printJob.Write(NativeOutputLocation.RequireWritableDestination(source,path),scor4Interface);printMenuFile=text;printMenuDirty=false;printStage=reading?OriginalPrintStage.ReadAcknowledgement:OriginalPrintStage.None;if(reading)printMenuNotice="**** Reading "+text+Environment.NewLine+"Press any key to continue.";RefreshPageFrame();return true;}
 // Original F6 accepts word READ/SAVE with a filename on this line;
 // numeric14/15 deliberately request a subsequent filename even with trailing text.
 if(upper=="READ"||upper.StartsWith("READ ")||upper.StartsWith("READ\t")||upper=="SAVE"||upper.StartsWith("SAVE ")||upper.StartsWith("SAVE\t")){bool reading=upper.StartsWith("READ");string filename=text.Length>4?text.Substring(4).Trim():"";printStage=reading?OriginalPrintStage.ReadFile:OriginalPrintStage.SaveFile;if(filename.Length!=0)return SubmitOriginalPrint(filename);RefreshOriginalPrintMenu();return true;}
 if(upper=="G"){RunOriginalPrint();return true;}if(text.Length==0){RefreshOriginalPrintMenu();return true;}int space=text.IndexOfAny(new[]{' ','\t'});string head=space<0?text:text.Substring(0,space),arg=space<0?"":text.Substring(space).Trim();int code;if(!Int32.TryParse(head,out code)||code<1||code>16)throw new InvalidDataException("Enter a print code from1 to16, or G.");string[] values=arg.Replace(',',' ').Split(new[]{' ','\t'},StringSplitOptions.RemoveEmptyEntries);float number;short word;
 switch(code){case 1:string name=arg;if(name.Length==0&&NativeDiskDialogChoice.Files){name=ChooseCommandFile("Choose EPS output",true,"EPS files (*.eps)|*.eps",String.IsNullOrEmpty(current)?"SCORE.EPS":Path.ChangeExtension(Path.GetFileName(current),".EPS"));if(name==null)return true;printJob.Output=name;break;}if(name==".")name=String.IsNullOrEmpty(current)?"SCORE.EPS":Path.ChangeExtension(Path.GetFileName(current),".EPS");else if(name.Length!=0&&!Path.HasExtension(name))name+=".EPS";if(name!="Laser"&&File.Exists(Path.IsPathRooted(name)?name:Path.Combine(NativeOutputLocation.Folder(source),name))){pendingPrintOutput=name;printStage=OriginalPrintStage.OutputOverwrite;}else printJob.Output=name;break;
 case 2:number=arg.Length==0?1:PrintValue(arg);if(number<=0)throw new InvalidDataException("Print size must be positive.");printJob.Size=number;break;
 case 3:if(arg.Length==0||arg.Equals("LTR",StringComparison.OrdinalIgnoreCase)){printJob.PaperWidth=8.5f;printJob.PaperHeight=11;}else if(arg.Equals("LEG",StringComparison.OrdinalIgnoreCase)){printJob.PaperWidth=8.5f;printJob.PaperHeight=14;}else if(arg.Equals("LDG",StringComparison.OrdinalIgnoreCase)){printJob.PaperWidth=11;printJob.PaperHeight=17;}else{if(values.Length!=2)throw new InvalidDataException("Enter a paper abbreviation or width and height in inches.");float x=PrintValue(values[0]),y=PrintValue(values[1]);if(x<=0||y<=0)throw new InvalidDataException("Paper dimensions must be positive.");printJob.PaperWidth=x;printJob.PaperHeight=y;}break;
 case 4:if(values.Length==0)break;if(values.Length!=2)throw new InvalidDataException("Enter left and bottom offsets in inches.");printJob.SetOffsets(PrintValue(values[0]),PrintValue(values[1]));break;
 case 5:printJob.Freeze=PrintBoolean(arg.ToUpperInvariant());break;
 case 6:if(arg.Length==0)break;word=PrintWord(arg);if(word<=0)throw new InvalidDataException("Resolution must be positive.");printJob.Resolution=word;printJob.LineWidth=(short)Math.Round(word/150.0,MidpointRounding.AwayFromZero);break;
 case 7:if(arg.Length!=0)printJob.LineWidth=PrintWord(arg);break;
 case 8:string kind=arg.ToUpperInvariant();if(kind=="H"||kind=="F"||kind=="B"){pendingPrintHeader=kind=="H"?"Header":kind=="F"?"Footer":"Both";printStage=OriginalPrintStage.Project;}else if(kind.Length==0||kind=="N"||kind=="0")printJob.Header="None";else throw new NotSupportedException("Header modes are H, F or B.");break;
 case 9:printJob.SetRotation(PrintBoolean(arg.ToUpperInvariant()));break;
 case 10:printJob.Mirror=PrintBoolean(arg.ToUpperInvariant());break;case 11:printJob.Stroke=PrintBoolean(arg.ToUpperInvariant());break;case 12:printJob.Manual=PrintBoolean(arg.ToUpperInvariant());break;case 13:word=arg.Length==0?(short)0:PrintWord(arg);if(word<0||word>9)throw new InvalidDataException("Tray number must be0–9.");printJob.Tray=word;break;
 case 14:printStage=OriginalPrintStage.ReadFile;break;case 15:printStage=OriginalPrintStage.SaveFile;break;
 case 16:if(scor4Interface)break;word=arg.Length==0?(short)0:PrintWord(arg);if(word<0||word>1)throw new InvalidDataException("DESC must be0 or1.");printJob.Desc=word;break;}
 if((code==14||code==15)&&NativeDiskDialogChoice.Files){
  string chosen=ChooseCommandFile(code==14?"Read print settings":"Save print settings",code==15,"SCORE settings (*.scr)|*.scr","PRINT.SCR");
  if(chosen!=null)return SubmitOriginalPrint(chosen);
  printStage=OriginalPrintStage.None;
 }
 if(code!=14&&code!=15)printMenuDirty=true;RefreshPageFrame();return true;}
