 void RunOriginalPrint(){if(printStage!=OriginalPrintStage.None)return;if(printJob==null)printJob=NativePrintJob.Defaults(source);if(BeginExternalDrawingRedraw(PrepareOriginalPrintOutput))return;PrepareOriginalPrintOutput();}
 void PrepareOriginalPrintOutput(){
  if(String.IsNullOrEmpty(printJob.Output)||printJob.Output.Equals("Laser",StringComparison.OrdinalIgnoreCase)){Print();return;}
  if(printJob.Freeze)printJob.ResolvedExtents=NativePrintMinimum.Extents(canvas);else printJob.Resolve(canvas);
